let audioCtx;
        let analyzer;
        let source;
        let isRunning = false;
        let animationId;
        const canvas = document.getElementById('spectrum-canvas');
        const ctx = canvas.getContext('2d');
        async function toggleAnalyzer() {
            if (isRunning) {
                stopAnalyzer();
            } else {
                startAnalyzer();
            }
        }
        async function startAnalyzer() {
            try {
                if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                source = audioCtx.createMediaStreamSource(stream);
                analyzer = audioCtx.createAnalyser();
                analyzer.fftSize = 4096;
                analyzer.smoothingTimeConstant = parseFloat(document.getElementById('smoothing').value);
                source.connect(analyzer);
                isRunning = true;
                document.getElementById('start-btn').innerHTML = '<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg><span>STOP ANALYZER</span>';
                document.getElementById('start-btn').classList.replace('bg-emerald-600', 'bg-red-600');
                requestAnimationFrame(draw);
            } catch (err) {
                alert("Microphone access denied. Cannot run analysis.");
            }
        }
        function stopAnalyzer() {
            isRunning = false;
            cancelAnimationFrame(animationId);
            if (source) source.disconnect();
            document.getElementById('start-btn').innerHTML = '<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"></path></svg><span>ACTIVATE MICROPHONE</span>';
            document.getElementById('start-btn').classList.replace('bg-red-600', 'bg-emerald-600');
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
        function updateSmoothing(val) {
            if (analyzer) analyzer.smoothingTimeConstant = parseFloat(val);
            document.getElementById('smooth-val').innerText = val;
        }
        function draw() {
            if (!isRunning) return;
            animationId = requestAnimationFrame(draw);
            const bufferLength = analyzer.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);
            analyzer.getByteFrequencyData(dataArray);
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            const barWidth = (canvas.width / bufferLength) * 2.5;
            let barHeight;
            let x = 0;
            let maxVal = 0;
            let maxIdx = 0;
            let totalSignal = 0;
            for (let i = 0; i < bufferLength; i++) {
                barHeight = dataArray[i];
                if (barHeight > maxVal) {
                    maxVal = barHeight;
                    maxIdx = i;
                }
                totalSignal += barHeight;
                // Color Gradient based on frequency (Low: Greenish, High: Bluish)
                const hue = (i / bufferLength) * 120 + 120;
                ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.8)`;
                // Draw log or linear
                let drawX = x;
                if (document.getElementById('log-scale').checked) {
                    // Logarithmic Strategy: Use Math.log to group lower frequencies together
                    drawX = (Math.log(i) / Math.log(bufferLength)) * canvas.width;
                }
                ctx.fillRect(drawX, canvas.height - (barHeight * (canvas.height / 255)), barWidth, barHeight * (canvas.height / 255));
                x += barWidth + 1;
            }
            // HUD Updates
            const nyquist = audioCtx.sampleRate / 2;
            const peakFreq = Math.round(maxIdx * nyquist / bufferLength);
            document.getElementById('peak-freq').innerText = peakFreq.toLocaleString() + " Hz";
            // Decibel approximation
            const db = Math.round(20 * Math.log10(totalSignal / (bufferLength * 128)));
            document.getElementById('signal-db').innerText = (isFinite(db) ? db : -90) + " dB";
            document.getElementById('peak-note').innerText = freqToNote(peakFreq);
        }
        function freqToNote(freq) {
            if (freq < 20) return "--";
            const notes = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
            // Pitch Detection Formula (LaTeX Style Logarithm)
            const h = Math.round(12 * Math.log2(freq / 440));
            const noteIdx = (h + 12 * 10 + 9) % 12;
            return notes[noteIdx];
        }
        function resize() {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }
        window.addEventListener('resize', resize);
        resize();
